	query := q.listDevicesByPrincipals

	args := make([]any, 0, 1+len(arg.Principals))

	args = append(args, arg.Scope)

	query = strings.Replace(query, "/*SLICE:principals*/?", slicePlaceholders("?", len(arg.Principals)), 1)

